import React from 'react';
import { motion } from 'framer-motion';
import { Wallet } from 'lucide-react';

/** Encabezado de la pantalla de Caja: ícono de marca + título + descripción. */
const CashierHeader = () => (
  <motion.div
    className="cashier-header"
    initial={{ opacity: 0, y: -8 }}
    animate={{ opacity: 1, y: 0 }}
    transition={{ duration: 0.35, ease: 'easeOut' }}
  >
    <span className="cashier-header-icon">
      <Wallet size={26} strokeWidth={2} />
    </span>
    <div>
      <h1 className="cashier-header-title">Caja y Facturación</h1>
      <p className="cashier-header-subtitle">Cobra pedidos, emite facturas e imprime tickets desde un solo lugar.</p>
    </div>
  </motion.div>
);

export default CashierHeader;
